<?php
declare(strict_types=1);
require_once __DIR__.'/lib/members_lib.php';
require_once __DIR__.'/file_share_lib.php';
if(empty($_SESSION['admin_logged_in'])){http_response_code(403);exit('접근 권한이 없습니다.');}
function fs_h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$message='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!site_valid_csrf()){http_response_code(403);exit('보안 토큰이 유효하지 않습니다.');}
 $id=(string)($_POST['id']??'');$action=(string)($_POST['action']??'');if(!fs_valid_id($id)){http_response_code(400);exit('파일 ID가 올바르지 않습니다.');}
 try{fs_locked(function(&$db,&$changed)use($id,$action){if(!isset($db['shares'][$id]))throw new RuntimeException('파일을 찾을 수 없습니다.');if($action==='block'){$db['shares'][$id]['blocked']=true;$changed=true;}elseif($action==='delete'){$path=fs_paths()['files'].'/'.$id;if(is_file($path)&&!@unlink($path))throw new RuntimeException('파일 삭제에 실패했습니다.');unset($db['shares'][$id]);$changed=true;}else throw new RuntimeException('알 수 없는 작업입니다.');});$message='작업을 완료했습니다.';}catch(Throwable $e){$message=$e->getMessage();}
}
try{$shares=fs_locked(function(&$db,&$changed){fs_cleanup_db($db,$changed);return $db['shares'];});}catch(Throwable $e){http_response_code(503);exit('저장소를 사용할 수 없습니다.');}
uasort($shares,fn($a,$b)=>(int)($b['created']??0)<=>(int)($a['created']??0));$csrf=site_csrf();
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>파일 공유 관리</title><style>body{font-family:system-ui;background:#111;color:#eee;padding:16px}main{max-width:1100px;margin:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #444;text-align:left}a{color:#8cc8ff}button{padding:8px 12px}form{display:inline-block;margin:3px}.wrap{overflow-x:auto}@media(max-width:600px){body{padding:8px}th,td{font-size:13px}}</style></head><body><main><h1>파일 공유 관리</h1><p><?=fs_h($message)?></p><p>전체 파일: <?=count($shares)?> · 다운로드 횟수는 전송 시작 기준이며 완료 횟수가 아닙니다.</p><div class="wrap"><table><thead><tr><th>업로더 ID</th><th>파일명</th><th>용량</th><th>다운로드</th><th>만료 일시</th><th>상태</th><th>관리</th></tr></thead><tbody><?php foreach($shares as $id=>$s): ?><tr><td><?=fs_h($s['owner']??'')?></td><td><?=fs_h($s['name']??'')?></td><td><?=number_format((int)($s['size']??0)/1048576,2)?> MiB</td><td><?=(int)($s['downloads']??0)?></td><td><?=date('Y-m-d H:i',(int)($s['expires']??0))?></td><td><?=!empty($s['blocked'])?'차단됨':(!fs_allowed((string)$s['owner'])||(int)($s['generation']??-1)!==fs_generation((string)$s['owner'])?'권한 회수':'활성')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=fs_h($csrf)?>"><input type="hidden" name="id" value="<?=fs_h($id)?>"><input type="hidden" name="action" value="block"><button type="submit">차단</button></form><form method="post" onsubmit="return confirm('이 파일을 삭제할까요? 삭제하면 복구할 수 없습니다.')"><input type="hidden" name="csrf" value="<?=fs_h($csrf)?>"><input type="hidden" name="id" value="<?=fs_h($id)?>"><input type="hidden" name="action" value="delete"><button type="submit">삭제</button></form></td></tr><?php endforeach; ?></tbody></table></div><p><a href="/admin_members.php">회원 관리로</a></p></main></body></html>
